if ref_count > 0:
    logging_util.emit_kv("LINT_STATUS", "findings")
    logging_util.emit_kv("RETIRED_PATHS", str(len(retired_set)))
    logging_util.emit_kv("RETIRED_REFS", str(ref_count))
